<#
.SYNOPSIS
  RankHound finish script — embeds your real logo + inits git + pushes.
  Run this AFTER rankhound-patch.ps1 has applied the branding files.

.DESCRIPTION
  This script:
    1. Embeds your real AI 4 EveryOne chip icon (274x276 PNG) as
       assets/rankhound-logo.png and assets/favicon.png
       (uses [System.IO.File]::WriteAllBytes — works on PowerShell 5.1+)
    2. Inits git on main with your identity
    3. Commits all changes (branding + logo)
    4. Adds remote pointing at github.com/QaisarMQM/rankhound
    5. Pushes (GitHub sign-in window pops up on first push)
#>
[CmdletBinding()]
param([switch]$SkipPush)

$ErrorActionPreference = 'Stop'

$GITHUB_USER = 'QaisarMQM'
$REPO_NAME  = 'rankhound'
$VERSION    = '2.11.0-rankhound.2'
$AUTHOR     = 'Muhammad Qaisar Abbas Malik'
$EMAIL      = 'qaisar.mqm@gmail.com'

function Write-Step { param($msg) Write-Host "`n>>> $msg" -ForegroundColor Green }
function Write-Sub  { param($msg) Write-Host "    $msg" -ForegroundColor Gray }
function Write-Err  { param($msg) Write-Host "!!  $msg" -ForegroundColor Red }

# Verify we're in the right folder
if (-not (Test-Path 'SKILL.md') -or -not (Test-Path 'pyproject.toml')) {
    Write-Err "This script must be run from INSIDE the rankhound-build folder."
    Write-Err "Current location: $(Get-Location)"
    Write-Err "Run: cd `$env:USERPROFILE\Downloads\rankhound-build"
    exit 1
}

# --- Step 1: Embed the real AI 4 EveryOne logo (correct method) ----------------------
Write-Step 'Embed real AI 4 EveryOne logo'
$logoB64 = ''
$logoBytes = [Convert]::FromBase64String($logoB64)
if (-not (Test-Path 'assets')) { New-Item -ItemType Directory -Path 'assets' | Out-Null }

# Use [System.IO.File]::WriteAllBytes — works on PowerShell 5.1 AND 7+
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) 'assets\rankhound-logo.png'), $logoBytes)
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) 'assets\favicon.png'),        $logoBytes)

$logoPath = Join-Path (Get-Location) 'assets\rankhound-logo.png'
$logoSize = (Get-Item $logoPath).Length
Write-Sub "assets/rankhound-logo.png ($logoSize bytes)"
Write-Sub "assets/favicon.png ($logoSize bytes)"

# --- Step 2: Init fresh git repo -----------------------------------------------------
Write-Step 'Initialize git repo with RankHound identity'
git init -q 2>&1 | Out-Null
git branch -M main 2>&1 | Out-Null
git config user.name  $AUTHOR
git config user.email $EMAIL
git add -A 2>&1 | Out-Null

$commitMsg = @"
v$VERSION - RankHound by AI 4 EveryOne

Forked from BeyondSEO v2.11.0 by Muhammad Tahir Ashraf (MIT License).
Enhanced and rebranded by $AUTHOR - AI 4 EveryOne,
recognized by Google AI (Dec 30, 2025) for building with Gemma 3 & Gemma 3n.

Changes in this fork:
- Renamed product to RankHound, studio to AI 4 EveryOne
- 4-color brand palette: emerald / amber / ink / cream
- Updated SKILL.md, pyproject.toml, CITATION.cff, README.md
- Added NOTICE.md (MIT attribution), ROADMAP.md (planned enhancements)
- Added rankhound CLI entry point alongside beyondseo alias
- Added real AI 4 EveryOne logo (274x276 PNG) to assets/
- No engine changes - Python modules identical to upstream v2.11.0

Original MIT license preserved. See LICENSE and NOTICE.md.
"@

git commit -q -m $commitMsg 2>&1 | Out-Null
$commitHash = (git log --oneline -1) 2>&1
$fileCount  = (git ls-files | Measure-Object).Count
Write-Sub "Commit: $commitHash"
Write-Sub "Files tracked: $fileCount"

# --- Step 3: Add remote + push -------------------------------------------------------
if ($SkipPush) {
    Write-Step 'Skipping push (-SkipPush was set)'
    Write-Host "`nRepo ready at: $(Get-Location)" -ForegroundColor Cyan
    Write-Host "To push later:" -ForegroundColor Cyan
    Write-Host "  git remote add origin https://github.com/$GITHUB_USER/$REPO_NAME.git" -ForegroundColor White
    Write-Host "  git push -u origin main" -ForegroundColor White
    exit 0
}

Write-Step "Add remote + push to github.com/$GITHUB_USER/$REPO_NAME"
$remoteUrl = "https://github.com/$GITHUB_USER/$REPO_NAME.git"
git remote remove origin 2>$null
git remote add origin $remoteUrl
Write-Sub "Remote: $remoteUrl"
Write-Sub 'Pushing (a GitHub sign-in window may pop up on first push)...'
git push -u origin main
if ($LASTEXITCODE -ne 0) {
    Write-Err "Push failed (exit code $LASTEXITCODE)."
    Write-Host "`nCommon causes:" -ForegroundColor Yellow
    Write-Host "  1. The GitHub repo doesn't exist yet - create it at https://github.com/new" -ForegroundColor Yellow
    Write-Host "     (Owner: $GITHUB_USER, Name: $REPO_NAME, Public, DON'T initialize with README)" -ForegroundColor Yellow
    Write-Host "  2. You're not signed in to GitHub - sign in when the popup appears" -ForegroundColor Yellow
    Write-Host "`nRepo is ready locally. Fix the issue above, then run:" -ForegroundColor Cyan
    Write-Host "  git push -u origin main" -ForegroundColor White
    exit 1
}

Write-Step 'SUCCESS'
Write-Host "`n  Repo live at: https://github.com/$GITHUB_USER/$REPO_NAME" -ForegroundColor Green
Write-Host "  Local copy:   $(Get-Location)`n" -ForegroundColor Green
